# -*- coding: utf-8 -*-
"""Abbreviations for the Renal Dietitian track: token -> (expansion, plain note). Merge into SHARED.ABBR
(generate_tech_courses.py) so auto_expand() and the glossary pick them up. Tokens already in the nursing or
shared tables (CKD, HD, PD, AKI, ICU, KDIGO, PTH, ...) are repeated here only when the dietitian note differs."""

ABBR = {
    "ADPKD": ("autosomal dominant polycystic kidney disease", "An inherited disease in which cysts grow in both kidneys."),
    "APD": ("automated peritoneal dialysis", "A machine performs peritoneal dialysis exchanges at night."),
    "ASPEN": ("American Society for Parenteral and Enteral Nutrition", "Publishes consensus guidance on refeeding and nutrition support."),
    "AUA": ("American Urological Association", "Publishes the kidney stone medical management guideline."),
    "BUN": ("blood urea nitrogen", "The urea level in blood, reflecting protein intake, muscle breakdown, and clearance."),
    "CGA": ("cause, GFR category, and albuminuria category", "The KDIGO way of describing chronic kidney disease."),
    "CGM": ("continuous glucose monitor", "A sensor that reads glucose every few minutes."),
    "CKM": ("conservative kidney management", "Planned care for kidney failure without dialysis, focused on symptoms and goals."),
    "CKRT": ("continuous kidney replacement therapy", "Dialysis run 24 hours a day in intensive care; also called CRRT."),
    "CPD": ("continuing professional development", "Credit for ongoing professional education; this series does not award it."),
    "CYP3A4": ("cytochrome P450 3A4", "An enzyme in the gut and liver that breaks down tacrolimus and many other medicines."),
    "ESPEN": ("European Society for Clinical Nutrition and Metabolism", "Publishes the hospital kidney nutrition and micronutrient guidelines."),
    "FGF23": ("fibroblast growth factor 23", "A bone hormone that makes the kidney excrete phosphorus."),
    "GLIM": ("Global Leadership Initiative on Malnutrition", "Criteria for diagnosing malnutrition in any adult."),
    "GLP-1 RA": ("glucagon-like peptide-1 receptor agonist", "A medicine that lowers glucose and appetite, such as semaglutide."),
    "IDPN": ("intradialytic parenteral nutrition", "Nutrients given into the dialysis circuit during hemodialysis."),
    "IDWG": ("interdialytic weight gain", "Weight gained between dialysis sessions; almost all fluid."),
    "ISPD": ("International Society for Peritoneal Dialysis", "Publishes peritoneal dialysis and peritonitis guidelines."),
    "ISRNM": ("International Society of Renal Nutrition and Metabolism", "The professional society for kidney nutrition."),
    "KDOQI": ("Kidney Disease Outcomes Quality Initiative", "The National Kidney Foundation guideline program; publishes the 2020 nutrition guideline."),
    "KRT": ("kidney replacement therapy", "Dialysis in any form, or a transplant."),
    "LPD": ("low-protein diet", "About 0.55 to 0.60 g of protein per kg a day."),
    "MIS": ("Malnutrition-Inflammation Score", "A 10-item nutrition score used in hemodialysis."),
    "MNT": ("medical nutrition therapy", "Assessment, prescription, counseling, and follow-up by a dietitian."),
    "NCP": ("Nutrition Care Process", "Assessment, diagnosis, intervention, and monitoring and evaluation."),
    "ONS": ("oral nutrition supplement", "A ready-made drink or powder that adds energy and protein."),
    "PDSA": ("Plan-Do-Study-Act", "A small test-of-change cycle used in quality improvement."),
    "PES": ("problem, etiology, signs and symptoms", "The format of a nutrition diagnosis."),
    "PEW": ("protein-energy wasting", "Loss of body protein and energy stores in kidney disease."),
    "PTDM": ("post-transplantation diabetes mellitus", "Diabetes that first appears after transplant."),
    "RAAS": ("renin-angiotensin-aldosterone system", "Hormones that control blood pressure and potassium; blocked by several kidney-protective medicines."),
    "RND": ("registered nutritionist-dietitian", "The Philippine license title for dietitians under Republic Act No. 10862."),
    "SARC-F": ("Strength, Assistance with walking, Rise from a chair, Climb stairs, Falls", "A five-question sarcopenia screen."),
    "SBAR": ("Situation, Background, Assessment, Recommendation", "A structure for clinical reports."),
    "SGA": ("Subjective Global Assessment", "A structured bedside nutrition rating; the 7-point version is used in dialysis."),
    "SGLT2": ("sodium-glucose cotransporter 2", "Target of medicines that make the kidney pass glucose in urine."),
    "UACR": ("urine albumin-to-creatinine ratio", "Albumin in a spot urine sample, corrected for concentration."),
    "VLPD": ("very low-protein diet", "About 0.28 to 0.43 g/kg/day with ketoanalogue or amino acid supplements."),
}
